function M:onEnter()
    self.m_fTime = 0
    self.m_attr_node = GameUtil:commonAttrNode(self.m_control, { mode = 14 })
    --获取组件
    local reward_list = self:findGameObject("reward_list")
    local radius_obj = self:findGameObject("radius_obj")
    local integral_rewards = self:findGameObject("integral_rewards")
    self.arrow = self:findGameObject("arrow")
    self.btn_one = self:findGameObject("btn_one")
    self.btn_ten = self:findGameObject("btn_ten")
