    local material_huang = self:findImage("material_huang")
    self.material_yellow = material_huang:GetComponent("Image").material
    local material_lan_1 = self:findImage("material_lan_1")
    self.material_blue_1 = material_lan_1:GetComponent("Image").material
    local material_lan_2 = self:findImage("material_lan_2")
    self.material_blue_2 = material_lan_2:GetComponent("Image").material

    --初始化页签
    self.tag_list = {}
    for k = 1, 2 do
        local img_select = self:findGameObject("tab_select_" .. k)
