        self.tag_list[k] = {img_select = img_select, img_select_fx = img_select_fx}
    end

    --奖池
    local fRadius = Vector3.Distance(radius_obj.transform.localPosition, self.arrow.transform.localPosition) --半径
    local angle = 360 / iconCount
    self.item_list = {}
    for i = 1, iconCount do
        local item = ResourceUtil:LoadUIGameObject("Common/ItemNode", Vector3.zero, nil)
        item.transform.localScale = Vector3.New(0.9, 0.9, 0.9)
        item.transform:SetParent(reward_list.transform, false)
        local x = fRadius * math.sin((angle * (i - 1)) * (math.pi / 180))
        local y = fRadius * math.cos((angle * (i - 1)) * (math.pi / 180))
        item.transform.localPosition = Vector2.New(x, y)
        local fx_compass = GameUtil:createPrefab("Compass/fx_compass", item.transform)
        local luaBehaviour = UIUtil.findLuaBehaviour(fx_compass)
        local img_fx = luaBehaviour:FindGameObject("img_fx")
        local rotation_z = -angle * (i - 1)
        img_fx.transform.localEulerAngles = Vector3.New(0, 0, rotation_z)
        local img_finish = luaBehaviour:FindGameObject("img_finish")
        local UI_Reward_LingQu_003 = luaBehaviour:FindGameObject("UI_Reward_LingQu_003")
        local ShuaXin_001 = luaBehaviour:FindGameObject("UI_Compass_ShuaXin_001")
        local ShuaXin_002 = luaBehaviour:FindGameObject("UI_Compass_ShuaXin_002")
        local img_select_1 = luaBehaviour:FindGameObject("UI_Compass_SBaoZha_001")
        local img_select_2 = luaBehaviour:FindGameObject("UI_Compass_SBaoZha_002")
        local img_select_3 = luaBehaviour:FindGameObject("UI_Compass_FBaoZha_001")
        local img_select_4 = luaBehaviour:FindGameObject("UI_Compass_FBaoZha_002")
        img_select_1.transform.localEulerAngles = Vector3.New(0, 0, rotation_z)
        img_select_2.transform.localEulerAngles = Vector3.New(0, 0, rotation_z)
        img_select_3.transform.localEulerAngles = Vector3.New(0, 0, -rotation_z)
        img_select_4.transform.localEulerAngles = Vector3.New(0, 0, -rotation_z)
        self.item_list[i] = { item = item, img_fx = img_fx, img_finish = img_finish,
                              UI_Reward_LingQu_003 = UI_Reward_LingQu_003, ShuaXin_001 = ShuaXin_001,
                              ShuaXin_002 = ShuaXin_002, img_select_1 = img_select_1, img_select_2 = img_select_2 }
    end

    --大中小吉遮罩
    self.img_luck_list = {}
    for j = 1, 8 do
        self.img_luck_list[j] = {}
        local img_luck = self:findImage("img_luck_" .. j)
        local img_select = self:findGameObject("UI_Compass_HuoJiang_00" .. j)
        local fx_n = self:findGameObject("n_" .. j)
        local fx_s = self:findGameObject("s_" .. j)
        self.img_luck_list[j] = { img_luck = img_luck.gameObject, img_name = "img_luck_" .. j, img_select = img_select, fx_n = fx_n, fx_s = fx_s }
    end

    --左侧幸运奖励
    self.double_item = {}
    for m = 1, 3 do
        self.double_item[m] = {}
        local item = self:findGameObject("double_" .. m)
        local luaBehaviour = UIUtil.findLuaBehaviour(item)
        local item_node = luaBehaviour:FindGameObject("ItemNode")
        self.double_item[m] = { item_node = item_node, luaBehaviour = luaBehaviour }
    end

    --右侧幸运值奖励
    self.point_item = {}
    for n = 1, 9 do
        local item = ResourceUtil:LoadUIGameObject("Common/ItemNode", Vector3.zero, nil)
        item.transform.localScale = Vector3.New(0.74, 0.74, 0.74)
        item.transform:SetParent(integral_rewards.transform, false)
        local red_point = GameUtil:createPrefab("Compass/red_point", item.transform)
        local luaBehaviour = UIUtil.findLuaBehaviour(red_point)
        self.point_item[n] = { item = item, luaBehaviour = luaBehaviour }
        UIUtil.setButtonClick(red_point, function()
            self.m_control:GetIntegralReward(n)
        end)
    end

    self:switchTabNode(1)
	UserDataManager:removeRedDotByKey("roulette_once")
    self.m_update_key = "turntable"
    GameMain.addUpdate(self.m_update_key, handler(self, self.update))
end

function M:update()
    --if GameUtil:getpPlatform() == "Editor" then
    --    if CS.UnityEngine.Input.GetKeyUp(CS.UnityEngine.KeyCode.F3) then
    --        self.s = true
    --    end
    --    if CS.UnityEngine.Input.GetKeyUp(CS.UnityEngine.KeyCode.F4) then
    --        self.s = false
    --        self.turntable_2.transform.rotation = Quaternion.Euler(0, 0, 0)
    --    end
    --end
    if self.s_turntable_2 then
        if self.turntable_2.transform.eulerAngles.z < 180 then
            self.turntable_2.transform.rotation = CS.UnityEngine.Quaternion.RotateTowards(self.turntable_2.transform.rotation, CS.UnityEngine.Quaternion.Euler(0, 0, -180), 4)
        else
            self.turntable_2.transform.rotation = CS.UnityEngine.Quaternion.RotateTowards(self.turntable_2.transform.rotation, CS.UnityEngine.Quaternion.Euler(0, 0, 359.5), 4)
        end
    end
    if self.go then
        self.m_fTime = self.m_fTime + CS.UnityEngine.Time.deltaTime
        if self.m_fTime < 0.5 then
            self.m_fVelocity = 30 * self.m_fTime
            if self.m_fVelocity < 3 then
                self.m_fVelocity = 3
            end
        elseif self.m_fTime >= 1 then
            self.m_fVelocity = 150 / (10 ^ self.m_fTime)
        end
        if (self.m_fVelocity <= 2.5) then
            self.m_fVelocity = 2.5
            local prize_index = self.m_model.roulette_block_cfg[self.m_model.cur_index][self.m_control.block_id].block_number
            local lucky_team = self.m_model.roulette_block_cfg[self.m_model.cur_index][self.m_control.block_id].lucky_team
            local value = ((48 - (prize_index)) * 7.5) + 3.75
            local diff = self.arrow.transform.eulerAngles.z - value
            if self.arrow.transform.eulerAngles.z == 0 then
                diff = 360 - value
            end
            if (math.abs(diff) <= 2) then
                --local quaternion = self.arrow.transform.rotation
                --self.arrow.transform.rotation = CS.UnityEngine.Quaternion.Slerp(quaternion, CS.UnityEngine.Quaternion.Euler(Vector3.New(0, 0, value)), CS.UnityEngine.Time.deltaTime)
                --if (self.arrow.transform.rotation == CS.UnityEngine.Quaternion.Euler(Vector3.New(0, 0, value))) then
                if self.time == nil then
                    self.time = self.m_fTime
                end
                self:PlayResultFx(self.m_control.prize - 1, lucky_team)
                self.arrow.transform.rotation = Quaternion.Euler(0, 0, value)
                if self.m_fTime >= self.time + 0.8 then
                    self.time = nil
                    self.m_fVelocity = 0
                    self.m_fVelocity_2 = 0
                    self.m_fTime = 0
                    self.start = false
                    self.go = false
                    self.s_turntable_2 = false
                    self.turntable_2.transform.rotation = Quaternion.Euler(0, 0, 360)
                    if next(self.m_model.reward) then
                        RewardUtil:rewardTipsByRewards(self.m_model.reward)
                        self:refreshUI()
                    end
                end
                --end
            else
                self.arrow.transform:Rotate(Vector3.forward, (-1) * self.m_fVelocity)
                local index = math.floor((360 - self.arrow.transform.localEulerAngles.z) / 30)
                self:PlayFx(index)
            end
        else
            self.arrow.transform:Rotate(Vector3.forward, (-1) * self.m_fVelocity)
            local index = math.floor((360 - self.arrow.transform.localEulerAngles.z) / 30)
            self:PlayFx(index)
        end
    end
end

--选择页签
function M:switchTabNode(index)
    if self.start then
        return
    end
    if index == self.m_model.cur_index then
        return
    else
        self.arrow.transform.localEulerAngles = Vector3.New(0, 0, 0)
        for k, v in pairs(self.tag_list) do
            if k == index then
                v.img_select:SetActive(true)
                v.img_select_fx:SetActive(true)
            else
                v.img_select:SetActive(false)
                v.img_select_fx:SetActive(false)
            end
        end
        self.m_model.cur_index = index
        if index == 1 then
            self:setObjectVisible("img_arrow_1", true)
            self:setObjectVisible("img_arrow_2", false)
            self:setImg("a_xyzp_baguapan", "active_ui", "turntable_3")
            GameUtil:updateResourcesImg(self.turntable, "Texture/active/a_xyzp_jainglipan")
            GameUtil:updateResourcesImg(self.turntable_2, "Texture/active/a_xyzp_xuanzhuanpan")
        else
            self:setObjectVisible("img_arrow_1", false)
            self:setObjectVisible("img_arrow_2", true)
            self:setImg("a_xyzp_super_baguapan", "active_ui", "turntable_3")
            GameUtil:updateResourcesImg(self.turntable, "Texture/active/a_xyzp_super_jianglipan")
            GameUtil:updateResourcesImg(self.turntable_2, "Texture/active/a_xyzp_super_xuanzhuangpan")
        end
        self.turntable_img:SetNativeSize()
        self.turntable_2_img:SetNativeSize()
        self.turntable_3_img:SetNativeSize()
        self:refreshUI()
    end
end

function M:refreshUI()
    self:updateSkipAnimStatus()
    self:setObjectVisible("UI_Compass_JiHuo_001", false)
    self:setObjectVisible("UI_Compass_Glow_002", false)
    local all_point = self.m_model.data.goods.point[tostring(self.m_model.cur_index)]
    local pool_data = self.m_model.data.goods.luckys[tostring(self.m_model.cur_index)]
    local point_cfg = self.m_model:GetRoulettePointDataByType(self.m_model.cur_index)
    local block_data = self.m_model.data.goods.lucky_goods[tostring(self.m_model.cur_index)]
    local block_cfg = self.m_model:GetRouletteBlockDataByType(self.m_model.cur_index)
    self:setText("txt_point_value", all_point)
    for k, v in pairs(self.item_list) do
        v.img_finish:SetActive(false)
        v.img_fx:SetActive(false)
        v.UI_Reward_LingQu_003:SetActive(false)
        local data = pool_data[tostring(k)]
        if k == 1 or k == 4 or k == 7 or k == 10 then
            v.UI_Reward_LingQu_003:SetActive(true)
            --self:RefreshCommonItemEffect(data.reward, v)
        end
        GameUtil:updateItemElement(v.item, data.reward, true, true)
        for kk, vv in pairs(self.m_model.data.goods.bigprice[tostring(self.m_model.cur_index)]) do
            if k == vv then
                v.img_finish:SetActive(true)
                v.UI_Reward_LingQu_003:SetActive(false)
                break
            end
        end
    end
    for m, n in pairs(self.point_item) do
        local data = point_cfg[m]
        if data then
            n.item:SetActive(true)
            local reward = self.m_model:getRightListReward(data) -- 获取当前赛季奖励
            GameUtil:updateItemElement(n.item, reward, true, true)
            LuaBehaviourUtil.setText(n.luaBehaviour, "point_value", data.point)
            local flag = false
            if self.m_model.data.goods.point_index[tostring(self.m_model.cur_index)] and self.m_model.data.goods.point_index[tostring(self.m_model.cur_index)][tostring(m)] then
                flag = true
            end
            LuaBehaviourUtil.setObjectVisible(n.luaBehaviour, "btn_point", (all_point >= data.point) and not flag)
            LuaBehaviourUtil.setObjectVisible(n.luaBehaviour, "img_finish", flag)
            if (all_point >= data.point) and not flag then
                self:RefreshCommonItemEffect(reward, n)
            else
                LuaBehaviourUtil.setObjectVisible(n.luaBehaviour, "UI_RewardHeroDispatchPop_TuBiao_Blue01", false)
                LuaBehaviourUtil.setObjectVisible(n.luaBehaviour, "UI_RewardHeroDispatchPop_TuBiao_Col01", false)
                LuaBehaviourUtil.setObjectVisible(n.luaBehaviour, "UI_RewardHeroDispatchPop_TuBiao_Green01", false)
                LuaBehaviourUtil.setObjectVisible(n.luaBehaviour, "UI_RewardHeroDispatchPop_TuBiao_Red01", false)
                LuaBehaviourUtil.setObjectVisible(n.luaBehaviour, "UI_RewardHeroDispatchPop_TuBiao_Violet01", false)
                LuaBehaviourUtil.setObjectVisible(n.luaBehaviour, "UI_RewardHeroDispatchPop_TuBiao_Yellow01", false)
            end
        else
            n.item:SetActive(false)
        end
    end
    for j, l in pairs(self.img_luck_list) do
        l.img_luck:SetActive(false)
        l.img_select:SetActive(false)
        l.fx_n:SetActive(false)
        l.fx_s:SetActive(false)
    end
    for o, p in pairs(self.double_item) do
        local data = block_data[o]
        local cfg = block_cfg[data.lucky_team]
        LuaBehaviourUtil.setText(p.luaBehaviour, "name", cfg.name)
        LuaBehaviourUtil.setText(p.luaBehaviour, "statue", Language:getTextByKey("compass_str_008_" .. o))
        local index = data.lucky_team
        self.img_luck_list[index].img_luck:SetActive(true)
        if o == 1 then
            if self.m_model.cur_index == 1 then
                self:setImg("a_xyzp_lucky_red", "active_ui", self.img_luck_list[index].img_name)
                self.img_luck_list[index].fx_n:SetActive(true)
            else
                self:setImg("a_xyzp_super_red", "active_ui", self.img_luck_list[index].img_name)
                self.img_luck_list[index].fx_s:SetActive(true)
            end
            self.img_luck_list[index].img_luck:GetComponent("Image").material = self.material_red
        elseif o == 2 then
            if self.m_model.cur_index == 1 then
                self:setImg("a_xyzp_lucky_gold", "active_ui", self.img_luck_list[index].img_name)
                self.img_luck_list[index].fx_n:SetActive(true)
            else
                self:setImg("a_xyzp_super_gold", "active_ui", self.img_luck_list[index].img_name)
                self.img_luck_list[index].fx_s:SetActive(true)
            end
            self.img_luck_list[index].img_luck:GetComponent("Image").material = self.material_yellow
        elseif o == 3 then
            if self.m_model.cur_index == 1 then
                self:setImg("a_xyzp_lucky_blue", "active_ui", self.img_luck_list[index].img_name)
                self.img_luck_list[index].fx_n:SetActive(true)
                self.img_luck_list[index].img_luck:GetComponent("Image").material = self.material_blue_1
            else
                self:setImg("a_xyzp_super_blue", "active_ui", self.img_luck_list[index].img_name)
                self.img_luck_list[index].fx_s:SetActive(true)
                self.img_luck_list[index].img_luck:GetComponent("Image").material = self.material_blue_2
            end
        end
        if table.nums(data.goods) > 1 then
            LuaBehaviourUtil.setObjectVisible(p.luaBehaviour, "ItemNode", true)
            LuaBehaviourUtil.setObjectVisible(p.luaBehaviour, "des", false)
            GameUtil:updateItemElement(p.item_node, data.goods, true, true)
        else
            LuaBehaviourUtil.setObjectVisible(p.luaBehaviour, "ItemNode", false)
            LuaBehaviourUtil.setObjectVisible(p.luaBehaviour, "des", true)
            LuaBehaviourUtil.setText(p.luaBehaviour, "des", Language:getTextByKey("compass_str_001", data.goods[1]))
        end
    end
    local ten_need = ConfigManager:getCommonValueById(363)
    local one_need = ConfigManager:getCommonValueById(375)
    if self.m_model.cur_index == 2 then
        ten_need = ConfigManager:getCommonValueById(364)
        one_need = ConfigManager:getCommonValueById(376)
    end
    local itemData = RewardUtil:getProcessRewardData(one_need)
    local itemData_ten = RewardUtil:getProcessRewardData(ten_need)
    UIUtil.setImg(self.btn_one.transform, itemData.icon_name, "item_icon", "Image/Image")
    UIUtil.setText(self.btn_one.transform, itemData.data_num, "Image/value")

    UIUtil.setImg(self.btn_ten.transform, itemData_ten.icon_name, "item_icon", "Image/Image")
    UIUtil.setText(self.btn_ten.transform, itemData_ten.data_num, "Image/value")
    self:CheckRedPoint()
    self:RefreshStage()
    self:refreshLimitTimes()
    self:refreshRefreshLimitTimes()
end

function M:refreshRefreshLimitTimes()
    self:setObjectVisible("refresh_times_text", self.m_model:getNextRefresh() > 0)
    local _, max_times = self.m_model:getMaxTimes()
    local refresh_times = math.min(self.m_model:getRTimes(), max_times)
    self:setText("refresh_times_text", Language:getTextByKey("new_str_1072") ..  refresh_times .. "/" .. max_times)
end

function M:refreshLimitTimes()
    local max_times = self.m_model:getMaxTimes()
    local day_times = math.min(self.m_model:getDayTimes(), max_times)
    self:setText("max_times_text", Language:getTextByKey("tid#limit_2") ..  day_times .. "/" .. self.m_model:getMaxTimes())
end

function M:RefreshStage()
    local last_id = self.m_model.m_data.goods.refresh_stage[tostring(self.m_model.cur_index)]
    self:setObjectVisible("bg_stage", false)
    local map_id = UserDataManager:getBattleStage()
    local stage_tab = ConfigManager:getCfgByName("stage")
    local common_id = 388
    if self.m_model.cur_index == 2 then
        common_id = 387
    end
    local stage_list = ConfigManager:getCfgByName("common")[common_id].value
    local limit_id = nil
    for k, v in pairs(stage_list) do
        if map_id < v then
            limit_id = v
            break
        end
    end
    local next_id = nil
    for kk, vv in pairs(stage_list) do
        if last_id < vv then
            next_id = vv
            break
        end
    end
    if next_id and map_id >= next_id then
        self.m_model.refresh_tips = true
    else
        self.m_model.refresh_tips = false
    end
    if limit_id then
        local str = Language:getTextByKey(stage_tab[limit_id].map_point_name)
        self:setObjectVisible("bg_stage", true)
        self:setText("stage_name", string.format("通过%s后可以刷新出更好奖品", str))
        self:setText("stage_name", Language:getTextByKey("new_str_0824", str))
    end
end

function M:RefreshCommonItemEffect(data, v)
    local reward = RewardUtil:getProcessRewardData(data)
    LuaBehaviourUtil.setObjectVisible(v.luaBehaviour, "UI_RewardHeroDispatchPop_TuBiao_Blue01", false)
    LuaBehaviourUtil.setObjectVisible(v.luaBehaviour, "UI_RewardHeroDispatchPop_TuBiao_Col01", false)
    LuaBehaviourUtil.setObjectVisible(v.luaBehaviour, "UI_RewardHeroDispatchPop_TuBiao_Green01", false)
    LuaBehaviourUtil.setObjectVisible(v.luaBehaviour, "UI_RewardHeroDispatchPop_TuBiao_Red01", false)
    LuaBehaviourUtil.setObjectVisible(v.luaBehaviour, "UI_RewardHeroDispatchPop_TuBiao_Violet01", false)
    LuaBehaviourUtil.setObjectVisible(v.luaBehaviour, "UI_RewardHeroDispatchPop_TuBiao_Yellow01", false)
    if reward.quality == 1 or reward.quality == 2 then
        LuaBehaviourUtil.setObjectVisible(v.luaBehaviour, "UI_RewardHeroDispatchPop_TuBiao_Green01", true)
    elseif reward.quality == 3 or reward.quality == 4 then
        LuaBehaviourUtil.setObjectVisible(v.luaBehaviour, "UI_RewardHeroDispatchPop_TuBiao_Blue01", true)
    elseif reward.quality == 5 or reward.quality == 6 then
        LuaBehaviourUtil.setObjectVisible(v.luaBehaviour, "UI_RewardHeroDispatchPop_TuBiao_Violet01", true)
    elseif reward.quality == 7 or reward.quality == 8 then
        LuaBehaviourUtil.setObjectVisible(v.luaBehaviour, "UI_RewardHeroDispatchPop_TuBiao_Yellow01", true)
    elseif reward.quality == 9 or reward.quality == 10 then
        LuaBehaviourUtil.setObjectVisible(v.luaBehaviour, "UI_RewardHeroDispatchPop_TuBiao_Red01", true)
    elseif reward.quality >= 10 then
        LuaBehaviourUtil.setObjectVisible(v.luaBehaviour, "UI_RewardHeroDispatchPop_TuBiao_Col01", true)
    else
        LuaBehaviourUtil.setObjectVisible(v.luaBehaviour, "UI_RewardHeroDispatchPop_TuBiao_Violet01", true)
    end
end

--抽卡红点
function M:CheckRedPoint()
    local ten_need = ConfigManager:getCommonValueById(363)
    local one_need = ConfigManager:getCommonValueById(375)
    if self.m_model.cur_index == 2 then
        ten_need = ConfigManager:getCommonValueById(364)
        one_need = ConfigManager:getCommonValueById(376)
    end
    local OneItemData = RewardUtil:getProcessRewardData(one_need)
    local itemData = RewardUtil:getProcessRewardData(ten_need)
    self:setObjectVisible("one_red_point", OneItemData.user_num >= OneItemData.data_num)
    self:setObjectVisible("ten_red_point", itemData.user_num >= itemData.data_num)
    self:CheckTabRedPoint()
end

--页签红点
function M:CheckTabRedPoint()
    for i = 1, 2 do
        local ten_need = {}
        local one_need = {}
        if i == 1 then
            ten_need = ConfigManager:getCommonValueById(363)
            one_need = ConfigManager:getCommonValueById(375)
        else
            ten_need = ConfigManager:getCommonValueById(364)
            one_need = ConfigManager:getCommonValueById(376)
        end
        local OneItemData = RewardUtil:getProcessRewardData(one_need)
        local itemData = RewardUtil:getProcessRewardData(ten_need)
        local flag = false
        
        if OneItemData.user_num >= OneItemData.data_num then
            flag = true
        end
        if itemData.user_num >= itemData.data_num then
            flag = true
        end

        local red_point_click = UserDataManager.red_dot["compass_red_point_click"].status
        if self.m_model.cur_index == 2 then
            UserDataManager.red_dot["compass_red_point_click"].status = 2
        end
        if red_point_click == 1 and i == 1 then
            flag = false
        elseif red_point_click == 2 then
            flag = false
        end
        
        local point_cfg = self.m_model:GetRoulettePointDataByType(i)
        local all_point = self.m_model.data.goods.point[tostring(i)]
        
        for k, v in pairs(self.point_item) do
            local red_flag = false
            if self.m_model.data.goods.point_index[tostring(i)] and self.m_model.data.goods.point_index[tostring(i)][tostring(k)] then
                red_flag = true
            end
            local data = point_cfg[k]
            if data then
                if all_point >= data.point and not red_flag then
                    flag = true
                    break
                end
            end
        end
        
        self:setObjectVisible("red_point_" .. i, flag)
    end
end

--播放转动选中特效
function M:PlayFx(index)
    for k, v in pairs(self.item_list) do
        if (k - 1) == index then
            v.img_fx:SetActive(false)
            v.img_fx:SetActive(true)
        end
    end
end

--播放选中结果特效
function M:PlayResultFx(index, block_team)
    if self.is_play then
        return
    end
    audio:SendEvtUI("UI_TanCeOK")
    self.is_play = true
    local flag = false
    local block_data = self.m_model.data.goods.lucky_goods[tostring(self.m_model.cur_index)]
    for o, p in pairs(self.double_item) do
        local data = block_data[o]
        if block_team == data.lucky_team then
            flag = true
            break
        end
    end
    if flag then
        self.img_luck_list[block_team].img_select:SetActive(false)
        self.img_luck_list[block_team].img_select:SetActive(true)
    end
    self.m_control:setOnceTimer(0.25, function()
        for m, n in pairs(self.item_list) do
            if (m - 1) == index then
                if self.m_model.cur_index == 1 then
                    n.img_select_2:SetActive(false)
                    n.img_select_2:SetActive(true)
                else
                    n.img_select_1:SetActive(false)
                    n.img_select_1:SetActive(true)
                end
            end
        end
    end)
end

--跳过按钮状态
function M:updateSkipAnimStatus()
    self:setObjectVisible("skip_anim_open_img", self.m_model.m_skip_anim_flag == true)
    self:setObjectVisible("skip_anim_close_img", self.m_model.m_skip_anim_flag == false)
end

function M:destroy()
    GameMain.removeUpdate(self.m_update_key)
    self.m_fTime = 0
    self.m_fVelocity = 0
    self.m_fVelocity_2 = 0
    self.time = nil
    self.start = false
    self.go = false
    self.start_2 = false
    if self.m_attr_node then
        self.m_attr_node:destroy()
        self.m_attr_node = nil
    end
    M.super.destroy(self)
end

return M